import re
from collections import Counter
docs = context.split("=== DOCUMENT BREAK ===")
def all_orgs(doc):
    subj = re.findall(r"\[ENT-\d+\]\s+(.+?)\n", doc)
    disp = re.findall(r"custody passed from the (.+?) to the (.+?)", doc)
    names = list(subj)
    for a, b in disp:
        names.append(a)
        names.append(b)
    return names

sets = [set(all_orgs(d)) for d in docs]
# filter to names that look like orgs (multi-word with capital)
def is_org(n):
    return len(n.split()) >= 2 and all(w[0].isupper() for w in n.split())
inter = {n for s in sets for n in s if is_org(n)}
# actually intersection
inter = sets[0] & sets[1] & sets[2]
inter = {n for n in inter if is_org(n)}
print(inter)

target = "Glincrowetofts Bonding Yard"
for i, d in enumerate(docs):
    print(i, d.count(target))

target = "Glincrowetofts Bonding Yard"
for i, d in enumerate(docs):
    print(i, target in d, d.count(target))

